PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, UNIQUE(providerId, accountId));
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER, updatedAt INTEGER);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE legacy_identities (legacy_id TEXT PRIMARY KEY, google_subject TEXT UNIQUE NOT NULL, migrated_user_id TEXT REFERENCES user(id));
CREATE TABLE dogs (id TEXT PRIMARY KEY, user_id TEXT REFERENCES user(id) ON DELETE CASCADE, legacy_owner TEXT REFERENCES legacy_identities(legacy_id), name TEXT NOT NULL, breed TEXT, age REAL, weight REAL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(user_id IS NOT NULL OR legacy_owner IS NOT NULL));
CREATE INDEX dogs_owner ON dogs(user_id);
CREATE TABLE ingredients (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, aliases TEXT NOT NULL DEFAULT '[]', tags TEXT NOT NULL DEFAULT '[]');
CREATE TABLE sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('product','science')), url TEXT NOT NULL, allowed_host TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, permission_basis TEXT NOT NULL DEFAULT '', image_permission TEXT NOT NULL DEFAULT '', min_interval_seconds INTEGER NOT NULL DEFAULT 10, last_fetch_at TEXT, last_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id TEXT PRIMARY KEY, legacy_id TEXT UNIQUE, name TEXT NOT NULL, brand TEXT NOT NULL DEFAULT '', variant TEXT NOT NULL DEFAULT '', market TEXT NOT NULL DEFAULT 'US', ingredients TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, source_id TEXT REFERENCES sources(id), source_url TEXT, image_key TEXT, image_permission TEXT, status TEXT NOT NULL DEFAULT 'published', verified_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX products_name ON products(name);
CREATE TABLE product_versions (product_id TEXT NOT NULL REFERENCES products(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(product_id,version));
CREATE TABLE comparisons (id TEXT PRIMARY KEY, dog_id TEXT NOT NULL REFERENCES dogs(id) ON DELETE CASCADE, user_id TEXT REFERENCES user(id) ON DELETE CASCADE, input TEXT NOT NULL, result TEXT NOT NULL, engine_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX comparisons_owner ON comparisons(user_id,dog_id);
CREATE TABLE evidence (id TEXT PRIMARY KEY, doi TEXT UNIQUE, pmid TEXT UNIQUE, title TEXT NOT NULL, abstract TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, published_at TEXT, study_type TEXT, species TEXT, retracted INTEGER NOT NULL DEFAULT 0, corrected INTEGER NOT NULL DEFAULT 0, checked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE comments (id TEXT PRIMARY KEY, ingredient_id TEXT REFERENCES ingredients(id), body TEXT NOT NULL, evidence_ids TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'pending', model TEXT, prompt_version TEXT, reviewed_by TEXT, reviewed_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, source_id TEXT REFERENCES sources(id), url TEXT, status TEXT NOT NULL DEFAULT 'queued', object_key TEXT, content_hash TEXT, error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX jobs_status ON jobs(status,created_at);
CREATE TABLE source_snapshots (source_id TEXT NOT NULL, url TEXT NOT NULL, content_hash TEXT NOT NULL, object_key TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(source_id,url));
CREATE TABLE proposals (id TEXT PRIMARY KEY, job_id TEXT REFERENCES jobs(id), kind TEXT NOT NULL, product_id TEXT REFERENCES products(id), payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reasons TEXT NOT NULL DEFAULT '[]', reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX proposals_status ON proposals(status,created_at);
CREATE TABLE usage (id TEXT PRIMARY KEY, month TEXT NOT NULL, category TEXT NOT NULL, reserved_usd REAL NOT NULL CHECK(reserved_usd>=0), model TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX usage_month ON usage(month,category);
CREATE TABLE audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alerts (id TEXT PRIMARY KEY, level TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
